    const allSpans = scanMarkdown(content);
    if (allSpans.length === 0) {
      new import_obsidian6.Notice("Color Math: No math expressions found in note.");
      return;
    }
    let newContent = content;
    const sorted = [...allSpans].sort((a, b) => b.start - a.start);
